templates/frontdoor/nginx_conf.epp:
pid /var/run/nginx.pid;

# set the number of worker processes based on the number of CPU cores
worker_processes auto;

# set a generous time limit for gracefully shutting down worker processes
worker_shutdown_timeout 60s;

# set limits on the maximum number of open files and simultaneous connections per worker process
# this is an educated guess on reasonable values (must have worker_rlimit_nofile > worker_connections)
worker_rlimit_nofile 16384;
events {
    worker_connections 8192;
}

http {

    # omit nginx server version
    server_tokens off;

    # set the name server based on whether Docker or Podman is being used
        resolver 127.0.0.11 valid=10s ipv6=off;

    # override the client address with that sent in the X-Forwarded-For header
    set_real_ip_from    0.0.0.0/0;
    real_ip_header      X-Forwarded-For;
    real_ip_recursive   on;

    # optimize the transmission of files
    sendfile            on;
    sendfile_max_chunk  20m;
    tcp_nopush          on;

    # enable resetting of timed-out connections to help reclaim memory
    reset_timedout_connection   on;

    # double most defaults for hash tables to reduce the chance of failing to build
    map_hash_bucket_size            64;
    server_names_hash_max_size      1024;
    server_names_hash_bucket_size   32;
    types_hash_max_size             2048;
    variables_hash_bucket_size      64;
    variables_hash_max_size         2048;

    # set the default MIME type for responses
    include mime.types;
    default_type text/html;

    # disable warnings about uninitialized variables
    uninitialized_variable_warn off;

    # enable logging of requests
    map $request_uri $loggable {
        default 1;
    }

    # configure logging
    log_format upstreaminfo '$remote_addr - [$remote_addr] - $remote_user [$time_local] "$request" $status $body_bytes_sent "$http_referer" "$http_user_agent" $request_length $request_time [$proxy_upstream_name] $upstream_addr $upstream_response_length $upstream_response_time $upstream_status';
    access_log      /dev/stdout upstreaminfo if=$loggable;
    error_log       /dev/stderr notice;
    log_subrequest  on;

    # retain the default nginx handling of requests without a "Connection" header
    map $http_upgrade $connection_upgrade {
        default          upgrade;
        ''               close;
    }

    map $http_x_forwarded_port $pass_server_port {
       default           $server_port;
    }

    # map port 442 to 443 for header X-Forwarded-Port
    map $pass_server_port $pass_port {
        442              443;
        default          $pass_server_port;
    }

    # Map a response error watching the header Content-Type
    map $http_accept $httpAccept {
        default          html;
        application/json json;
        application/xml  xml;
        text/plain       text;
    }

    map $httpAccept $httpReturnType {
        default          text/html;
        json             application/json;
        xml              application/xml;
        text             text/plain;
    }

    # Obtain best http host
    map $http_host $this_host {
        default          $http_host;
        ''               $host;
    }

    map $http_x_forwarded_host $best_http_host {
        default          $this_host;
    }

    # disable specifying the port in absolute redirects issued by nginx
    port_in_redirect    off;

    # turn on session caching to drastically improve performance
    ssl_session_cache   builtin:1000 shared:SSL:10m;
    ssl_session_timeout 10m;

    # slightly reduce the time-to-first-byte
    ssl_buffer_size 4k;

    # restrict TLS versions and ciphers for security
    ssl_protocols               TLSv1.2 TLSv1.3;
    ssl_ciphers                 'ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-RSA-CHACHA20-POLY1305:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384';
    ssl_ecdh_curve              secp384r1;

    server {
      listen 8081;

      location /health {
        access_log off;
        add_header Content-Type text/plain;
        return 200 'OK';
      }
    }

    server {
        server_name _;
        listen 8080 default_server reuseport backlog=511;
        return 301 https://$host$request_uri;
    }

    server {
        server_name _;
        set $proxy_upstream_name "-";
        set $true 0;
        listen 8443 default_server reuseport backlog=511 ssl;

        # configure TLS certificate file locations
        ssl_certificate         /certs/cert_chain.pem;
        ssl_certificate_key     /certs/private_key.pem;

        # enforce ssl on server side
        if ($scheme = http) {
            return 301 https://$best_http_host$request_uri;
        }

        client_max_body_size    0;
        port_in_redirect        off;
        proxy_connect_timeout   5s;
        proxy_redirect          off;
        proxy_http_version      1.1;
        proxy_buffer_size       "128k";
        proxy_buffers           4 "256k";

        # set custom headers in requests to proxied server
        proxy_set_header Host               $best_http_host;
        proxy_set_header X-Real-IP          $remote_addr;
        proxy_set_header X-Original-URI     $request_uri;
        proxy_set_header X-Scheme           $scheme;

        # allow WebSocket connections
        proxy_set_header Upgrade           $http_upgrade;
        proxy_set_header Connection        $connection_upgrade;

        # mitigate HTTPoxy Vulnerability
        # https://www.nginx.com/blog/mitigating-the-httpoxy-vulnerability-with-nginx/
        proxy_set_header Proxy              "";

        # in case of errors, try the next upstream server before returning an error
        proxy_next_upstream                 error timeout invalid_header http_502 http_503 http_504;

        # health checks in cloud providers require the use of port 80
        location /healthz {
            access_log off;
            return 200;
        }

        # this is required to avoid error if nginx is being monitored
        # with an external software (like sysdig)
        location /nginx_status {
            allow 127.0.0.1;
            allow ::1;
            deny all;

            access_log off;
            stub_status on;
        }

        location / {
            set $gatekeeper http://comply_gatekeeper:3001;
            proxy_pass $gatekeeper;
	        proxy_hide_header Cache-Control;
            proxy_hide_header Pragma;
            add_header Cache-Control "no-cache, no-store, must-revalidate";
            add_header Pragma "no-cache";

            proxy_set_header   Connection keep-alive;
            proxy_set_header   Host $host;
            proxy_cache_bypass $http_upgrade;

            proxy_set_header   X-Forwarded-For $proxy_add_x_forwarded_for;
	        proxy_set_header   X-Forwarded-Proto $scheme;

	        # WebSocket support
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";

            # Support non 443 installs
                    }

        # Toggle whether the Keycloak admin console/API is reachable via frontdoor at all
        # (CISC-7391 -- a coarser alternative to an IP allowlist: fully on or fully off,
        # not per-network). ^~ /auth/admin is more specific than the plain /auth block
        # below, so nginx always prefers this one for admin paths regardless of file order.
        location ^~ /auth/admin {
                        return 403;
                    }

        # Regular user-facing endpoints (SSO/login, /auth/realms/*, etc.) -- always
        # reachable regardless of admin_console_enabled above.
        location ^~ /auth {
            set $identity http://comply_identity:8080;

            proxy_pass $identity;

            proxy_hide_header Cache-Control;
            proxy_hide_header Pragma;
            add_header Cache-Control "no-cache, no-store, must-revalidate";
            add_header Pragma "no-cache";

            proxy_set_header   Connection keep-alive;
            proxy_set_header   Host $host;
            proxy_cache_bypass $http_upgrade;

            proxy_set_header   X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header   X-Forwarded-Proto $scheme;

            # Support non 443 installs
                    }

        location ^~ /api/public/ {
            set $scarpy http://comply_scarpy:8088;

            proxy_pass $scarpy;

            proxy_hide_header Cache-Control;
            proxy_hide_header Pragma;
            add_header Cache-Control "no-cache, no-store, must-revalidate";
            add_header Pragma "no-cache";

            proxy_set_header   Connection keep-alive;
            proxy_set_header   Host $host;
            proxy_cache_bypass $http_upgrade;
            proxy_set_header   X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header   X-Forwarded-Proto $scheme;

            # Support non 443 installs
                    }
    }
}

templates/mtls_proxy/nginx_conf.epp:
worker_processes auto;

error_log /dev/stderr debug;

events {
  worker_connections 8192;
}

http {

  # omit nginx server version
  server_tokens off;

    resolver 127.0.0.11 valid=10s ipv6=off;

  server {
    listen 8081;

    location /health {
      access_log off;
      add_header Content-Type text/plain;
      return 200 'OK';
    }
  }

  server {
    #include /etc/nginx-resolver/resolver.conf;

    # backlog option should match or exceed somaxconn on the underyling
    # k8s _node_, if this value exceeds somaxconn it will be silently
    # truncated which is fine, we just don't want the backlog (which
    # defaults to 512) to be smaller than somaxconn.
    listen 8080 ssl backlog=4096;

    ssl_certificate         /certs/tls.crt;
    ssl_certificate_key     /certs/tls.key;
    ssl_protocols           TLSv1.2;
        ssl_client_certificate /certs/ca.crt;
    ssl_verify_client       on;
        ssl_verify_depth        10;

    set $comply_ui http://comply_ui:3001;
    set $comply_scarpy http://comply_scarpy:8088;

    location /api/v3/core/store/report {
        # These three directives disable request buffering so that nginx
        # doesn't accept requests faster than the upstream can accept them.
        client_max_body_size 0;
        proxy_http_version 1.1;
        proxy_request_buffering off;

        proxy_pass  $comply_scarpy/api/v3/core/store/report;
    }

    location /api/v3/uc/store-report {
        # Same as /api/v3/core/store/report above -- without an explicit
        # location, this path fell through to nginx's default 1MB
        # client_max_body_size and rejected report uploads with 413 before
        # they ever reached scarp.
        client_max_body_size 0;
        proxy_http_version 1.1;
        proxy_request_buffering off;

        proxy_pass  $comply_scarpy/api/v3/uc/store-report;
    }

    location /api/v3/core/assessorVersion {
        proxy_pass  $comply_scarpy/api/v3/core/assessorVersion;
    }

    location /api/v3/core/desiredCompliance {
        proxy_pass  $comply_scarpy/api/v3/core/desiredCompliance$is_args$args;
    }

    location /assessor/windows {
        proxy_pass  $comply_ui/files/assessor/windows;
    }

    location /assessor/linux {
        proxy_pass  $comply_ui/files/assessor/linux;
    }

    location /assessor/mac {
        proxy_pass  $comply_ui/files/assessor/mac;
    }

  }
}
